+// backpressure-aware multiplexer for SSE/HTTP2 streaming
+func (m *Mux) pushChunk(chunk Chunk) error {
+    select {
+    case m.out <- chunk:
+        return nil
+    case <-time.After(m.flushTimeout):
+        // prioritize final chunks (function calls / end token)
+        if chunk.IsFinal {
+            m.forceFlush(chunk)
+            return nil
+        }
+        return ErrBackpressure
+    }
